let adminIdentity=null;
const adminRoleLabels={superadmin:'ผู้ดูแลสูงสุด',admin:'ผู้ดูแล'};
const adminActivityLabels={ticket_viewed:'ดู / พิมพ์ตั๋ว',slip_viewed:'ดูสลิป',tax_exported:'ส่งออก CSV ภาษี',report_exported:'ส่งออก CSV รายงาน',login:'เข้าสู่ระบบ',logout:'ออกจากระบบ',cash_recorded:'บันทึก / แก้ไขเงินสด',order_status:'เปลี่ยนสถานะยอดเงิน',order_edited:'แก้ไขรายการ',ticket_redeemed:'ตรวจรับตั๋ว',ticket_reissued:'ออกลิงก์ตั๋วใหม่',tax_created:'เพิ่มคำขอภาษี',tax_updated:'แก้ไขคำขอภาษี',settings_updated:'แก้ไขการตั้งค่า',poster_managed:'จัดการโปสเตอร์',blessing_managed:'จัดการคำอวยพร',user_created:'สร้างผู้ดูแล',user_updated:'แก้ไขสิทธิ์ / บัญชี',user_password_reset:'ตั้งรหัสผ่านผู้ใช้ใหม่',password_changed:'เปลี่ยนรหัสผ่านตนเอง'};
async function adminUserRequest(path,data){const r=await fetch('/api/admin/'+path,{cache:'no-store',...(data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{})});const d=await r.json();if(!r.ok)throw new Error(d.error||'ดำเนินการไม่สำเร็จ');return d;}
async function renderAdminUsers(body){
 body.innerHTML='<section class="card ui-card"><h2>ผู้ใช้งานผู้ดูแล</h2><p class="muted">ใช้บัญชีแยกคนเพื่อระบุผู้บันทึกและผู้จัดการรายการ · ปิดใช้งานแทนการลบ เพื่อเก็บประวัติ</p><button type="button" class="ui-btn ui-btn-primary" id="admin-user-add">＋ เพิ่มผู้ดูแล</button><p role="status" id="admin-users-status">กำลังโหลด…</p><div id="admin-users-list"></div></section>';
 body.querySelector('#admin-user-add').onclick=()=>openAdminUserEditor(null,body);
 try{const d=await adminUserRequest('users');if(!body.isConnected)return;body.querySelector('#admin-users-status').textContent=`ผู้ดูแล ${d.items.length} บัญชี`;body.querySelector('#admin-users-list').innerHTML=`<div class="admin-orders-scroll"><table class="ui-table"><thead><tr><th>ชื่อผู้ใช้</th><th>ชื่อแสดง</th><th>สิทธิ์</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody>${d.items.map(u=>`<tr><td>${esc(u.username)}</td><td>${esc(u.display_name)}</td><td>${adminRoleLabels[u.role]}</td><td>${u.active?'ใช้งาน':'ปิดใช้งาน'}</td><td><button type="button" class="ui-btn ui-btn-sm" data-user-edit="${u.id}">แก้ไข</button><button type="button" class="ui-btn ui-btn-sm ui-btn-outline" data-user-password="${u.id}">ตั้งรหัสผ่านใหม่</button></td></tr>`).join('')}</tbody></table></div>`;body.querySelectorAll('[data-user-edit]').forEach(b=>b.onclick=()=>openAdminUserEditor(d.items.find(u=>u.id===Number(b.dataset.userEdit)),body));body.querySelectorAll('[data-user-password]').forEach(b=>b.onclick=()=>openAdminPassword(d.items.find(u=>u.id===Number(b.dataset.userPassword))));}catch(e){if(body.isConnected)body.querySelector('#admin-users-status').textContent=e.message;}
}
function openAdminUserEditor(user,body){
 modal(`<section id="admin-user-editor"><h2>${user?'แก้ไขผู้ดูแล':'เพิ่มผู้ดูแล'}</h2><form id="admin-user-form">${user?`<p>ชื่อผู้ใช้ <b>${esc(user.username)}</b></p>`:'<label>ชื่อผู้ใช้<input class="ui-input ui-input-bordered" name="username" required pattern="[a-zA-Z0-9._-]{3,50}" minlength="3" maxlength="50" autocomplete="off"></label>'}<label>ชื่อผู้ดูแลที่แสดงในประวัติ<input class="ui-input ui-input-bordered" name="display_name" value="${esc(user?.display_name||'')}" required minlength="2" maxlength="150"></label><label>สิทธิ์<select class="ui-select ui-select-bordered" name="role">${Object.entries(adminRoleLabels).reverse().map(([k,v])=>`<option value="${k}" ${user?.role===k?'selected':''}>${v}</option>`).join('')}</select></label>${user?`<label class="admin-active-label"><input type="checkbox" name="active" ${user.active?'checked':''}>เปิดใช้งานบัญชี</label>`:'<label>รหัสผ่านเริ่มต้น<input class="ui-input ui-input-bordered" name="password" type="password" required minlength="8" maxlength="72" autocomplete="new-password"></label>'}<p class="muted">ผู้ดูแลสูงสุดจัดการบัญชีและข้อมูลรับชำระได้ · ผู้ดูแลจัดการรายการ เงินสด ตั๋ว และรายงานได้</p><button type="submit" class="ui-btn ui-btn-primary full">บันทึกผู้ดูแล</button><p id="admin-user-result" role="status"></p></form></section>`);
 const form=document.querySelector('#admin-user-form');form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('[type=submit]');b.disabled=true;try{const d=Object.fromEntries(new FormData(form));if(user)Object.assign(d,{id:user.id,revision:user.revision,active:form.elements.active.checked});await adminUserRequest(user?'users-update':'users-create',d);form.reset();closeModal();if(body.isConnected)admin();}catch(e){if(form.isConnected)form.querySelector('#admin-user-result').textContent=e.message;}finally{if(b.isConnected)b.disabled=false;}};
}
function openAdminPassword(user=null){
 modal(`<section id="admin-password-editor"><h2>${user?'ตั้งรหัสผ่านใหม่: '+esc(user.username):'เปลี่ยนรหัสผ่านของฉัน'}</h2><form id="admin-password-form"><label>รหัสผ่านปัจจุบันของคุณ<input name="current_password" type="password" class="ui-input ui-input-bordered" required autocomplete="current-password"></label><label>รหัสผ่านใหม่${user?'สำหรับบัญชีนี้':''}<input name="new_password" type="password" class="ui-input ui-input-bordered" required minlength="8" maxlength="72" autocomplete="new-password"></label><label>ยืนยันรหัสผ่านใหม่<input name="confirm_password" type="password" class="ui-input ui-input-bordered" required minlength="8" maxlength="72" autocomplete="new-password"></label><p class="muted">อย่างน้อย 8 ตัวอักษร · บัญชีที่เปลี่ยนรหัสผ่านจะต้องเข้าสู่ระบบใหม่</p><button type="submit" class="ui-btn ui-btn-primary full">บันทึกรหัสผ่านใหม่</button><p id="admin-password-result" role="status"></p></form></section>`);
 const form=document.querySelector('#admin-password-form');form.onsubmit=async e=>{e.preventDefault();if(form.elements.new_password.value!==form.elements.confirm_password.value){form.querySelector('#admin-password-result').textContent='รหัสผ่านใหม่ไม่ตรงกัน';return;}const b=form.querySelector('button');b.disabled=true;try{await adminUserRequest(user?'users-password':'password',{current_password:form.elements.current_password.value,new_password:form.elements.new_password.value,...(user?{id:user.id}:{})});form.reset();closeModal();if(!user||user.id===adminIdentity?.id){adminIdentity=null;adminOrders=[];adminSummary=null;admin();}else{modal('<h2>ตั้งรหัสผ่านใหม่แล้ว</h2><p>บัญชีนี้ต้องเข้าสู่ระบบด้วยรหัสผ่านใหม่</p>');}}catch(e){if(form.isConnected)form.querySelector('#admin-password-result').textContent=e.message;}finally{if(b.isConnected)b.disabled=false;}};
}
const adminActivityVersions=new WeakMap();
const adminTargetLabels={order:'รายการ',user:'บัญชีผู้ใช้',settings:'เว็บไซต์',poster:'โปสเตอร์',blessing:'คำอวยพร',report:'รายงาน'};
const adminOperationLabels={record:'บันทึกใหม่',link:'เชื่อมรายการเดิม',edit:'แก้ไข',add:'เพิ่ม',delete:'นำออก',toggle:'เปลี่ยนการแสดง'};
async function renderAdminActivity(body,ref='',page=1){
 const version=(adminActivityVersions.get(body)||0)+1;adminActivityVersions.set(body,version);
 body.innerHTML=`<section class="card ui-card"><h2>${ref?'ประวัติรายการ '+esc(ref):'ประวัติผู้ดำเนินการ'}</h2><p class="muted">บันทึกผู้ดำเนินการตั้งแต่เริ่มใช้บัญชีแยกคน · ประวัติเดิมยังเก็บอยู่ แต่ไม่มีชื่อผู้ดำเนินการย้อนหลัง</p><form id="activity-filter"><label>เลขอ้างอิงรายการ<input name="ref" class="ui-input ui-input-bordered" value="${esc(ref)}" maxlength="80"></label><button class="ui-btn ui-btn-outline">ค้นหาประวัติ</button></form><p id="activity-status" role="status">กำลังโหลด…</p><div id="activity-list"></div></section>`;
 body.querySelector('#activity-filter').onsubmit=e=>{e.preventDefault();renderAdminActivity(body,e.target.elements.ref.value.trim());};
 try{const d=await adminUserRequest('activity?'+new URLSearchParams({ref,page}));if(!body.isConnected||adminActivityVersions.get(body)!==version)return;body.querySelector('#activity-status').textContent=`พบ ${money(d.count)} เหตุการณ์ · หน้า ${d.page}`;body.querySelector('#activity-list').innerHTML=d.items.length?`<div class="admin-orders-scroll"><table class="ui-table"><thead><tr><th>วันเวลา</th><th>ผู้ดำเนินการ</th><th>การจัดการ</th><th>รายการ</th></tr></thead><tbody>${d.items.map(a=>`<tr><td>${new Date(a.created*1000).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'})}</td><td>${esc(a.actor_name)}<br><small>${esc(a.actor_username)}</small></td><td>${esc(adminActivityLabels[a.action]||a.action)}${a.details?.operation?'<br><small>'+esc(adminOperationLabels[a.details.operation]||a.details.operation)+'</small>':''}${a.details?.status?'<br>'+esc({pending:'รอตรวจสอบ',confirmed:'ยืนยันแล้ว',rejected:'ยกเลิก / ไม่ผ่าน'}[a.details.status]||a.details.status):''}</td><td>${esc(adminTargetLabels[a.target_type]||a.target_type)} · ${esc(a.details?.username||a.target_id)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">ยังไม่มีประวัติผู้ดำเนินการสำหรับตัวกรองนี้</p>';for(const [label,p,disabled] of [['ก่อนหน้า',page-1,page<=1],['ถัดไป',page+1,page*50>=d.count]]){const b=document.createElement('button');b.className='ui-btn ui-btn-sm';b.textContent=label;b.disabled=disabled;b.onclick=()=>renderAdminActivity(body,ref,p);body.querySelector('#activity-list').append(b);}}catch(e){if(body.isConnected&&adminActivityVersions.get(body)===version)body.querySelector('#activity-status').textContent=e.message;}
}
function openAdminActivity(ref){modal('<section id="admin-activity-editor"></section>');renderAdminActivity(document.querySelector('#admin-activity-editor'),ref);}
